import{salaryProgression,salaryAtStage,roundSalary}from'./salary-progression.js';import{salaryPreviewInputs}from'./guide-state.js';import{calculateLifestyle}from'./lifestyle.js';import{lifestyleIncomeRange}from'./lifestyle-story.js';import{expandedPayOpportunity}from'./expanded-pay.js';import{experienceBeforeRole}from'./education-routes.js';
export function explorerBudget(s,o){if(!s.guide?.lifestylePreset||!s.finance?.lifestyle)return{covers:null,amount:null,reason:'Lifestyle not assessed'};if(o.expandedDegree){const p=expandedPayOpportunity(s,o);return{covers:o.requiresExperience?false:p.meetsAtStart,amount:p.firstPay,reason:o.requiresExperience?'Experienced destination':p.firstPay===null?'Comparable first-paid-stage pay unavailable':'Entry pay proxy; planning assumption'};}
const goal=lifestyleIncomeRange(s.finance.lifestyle);if(!goal)return{covers:null,amount:null,reason:'Lifestyle inputs need review'};const stage=salaryProgression(o.id)?.paidTraining?.stageKey||'entry',amount=salaryAtStage(o.id,stage);if(!Number.isFinite(amount))return{covers:null,amount:null,reason:'Pay unavailable'};const b=calculateLifestyle(salaryPreviewInputs(s,o.id,stage));return{covers:experienceBeforeRole.has(o.id)?false:b.status==='illustration'?b.remaining>=0&&roundSalary(amount)>=goal.low:null,amount,reason:experienceBeforeRole.has(o.id)?'Experienced destination':'First paid stage under stated assumptions'};}
